import type { Metadata } from "next";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { requireAdmin } from "@/lib/auth-guard";
import { usersCol } from "@/lib/collections";
import { redirect } from "next/navigation";

export const metadata: Metadata = {
  title: "Students — Admin — BJS Prep",
  description: "Manage all registered students.",
};

export default async function StudentsPage() {
  const session = await requireAdmin();

  if (!session) {
    redirect("/login");
  }

  const students = await (await usersCol())
    .find({})
    .sort({ createdAt: -1 })
    .limit(50)
    .toArray();

  return (
    <div className="mx-auto max-w-6xl">
      <header className="flex flex-col gap-2 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="font-heading text-3xl font-bold text-primary lg:text-4xl">
            Students
          </h1>
          <p className="mt-2 text-base text-muted">
            {students.length} registered accounts.
          </p>
        </div>
      </header>

      <div className="mt-6 overflow-hidden rounded-lg border border-border bg-card">
        <div className="hidden grid-cols-12 gap-4 border-b border-border px-6 py-3 text-xs uppercase tracking-wide text-muted md:grid">
          <span className="col-span-4">Name</span>
          <span className="col-span-3">Email</span>
          <span className="col-span-2">Role</span>
          <span className="col-span-2">Tier</span>
          <span className="col-span-1 text-right">Action</span>
        </div>

        {students.map((student) => (
          <div
            key={student._id.toString()}
            className="grid grid-cols-1 gap-3 border-b border-border px-4 py-4 last:border-b-0 md:grid-cols-12 md:items-center md:gap-4 md:px-6"
          >
            <div className="md:col-span-4">
              <Link href={`/admin/students/${student._id.toString()}`} className="font-medium text-foreground hover:text-primary">
                {student.name}
              </Link>
              <p className="text-xs text-muted">{student.roll ?? "No roll"}</p>
            </div>

            <div className="md:col-span-3">
              <p className="text-sm text-foreground">{student.email}</p>
            </div>

            <div className="md:col-span-2">
              <Badge
                className={
                  student.role === "admin"
                    ? "border-amber-300 text-amber-700"
                    : "border-border text-muted"
                }
              >
                {student.role === "admin" ? "Admin" : "Student"}
              </Badge>
            </div>

            <div className="md:col-span-2">
              <Badge
                className={
                  student.tier === "UNIVERSITY"
                    ? "border-primary text-primary"
                    : "border-accent text-accent"
                }
              >
                {student.tier === "UNIVERSITY" ? "University" : "Other"}
              </Badge>
            </div>

            <div className="md:col-span-1 md:text-right">
              <Link href={`/admin/students/${student._id.toString()}`} className="text-sm text-primary hover:underline">
                View
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
